function solve(matrix) {
  const m = matrix.length;
  const n = matrix[0].length;
  const rowZero = new Array(m).fill(false);
  const colZero = new Array(n).fill(false);
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (matrix[i][j] === 0) {
        rowZero[i] = true;
        colZero[j] = true;
      }
    }
  }
  const res = matrix.map((row) => row.slice());
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (rowZero[i] || colZero[j]) res[i][j] = 0;
    }
  }
  return res;
}

function solve(matrix) {
  const m = matrix.length;
  const n = matrix[0].length;
  const res = matrix.map((row) => row.slice());
  let firstRowZero = false;
  let firstColZero = false;
  for (let j = 0; j < n; j++) if (matrix[0][j] === 0) firstRowZero = true;
  for (let i = 0; i < m; i++) if (matrix[i][0] === 0) firstColZero = true;
  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      if (matrix[i][j] === 0) {
        res[i][0] = 0;
        res[0][j] = 0;
      }
    }
  }
  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      if (res[i][0] === 0 || res[0][j] === 0) res[i][j] = 0;
    }
  }
  if (firstRowZero) {
    for (let j = 0; j < n; j++) res[0][j] = 0;
  }
  if (firstColZero) {
    for (let i = 0; i < m; i++) res[i][0] = 0;
  }
  return res;
}
